//! About ▸ Licences: LightCraft's own licence and notices, the bundled UI font's licence, and the
//! licence of every crate the app links. The crate list is `assets/licences/third-party.json`,
//! generated by `cargo xtask licences --write` and compiled in; nothing is read at run time.

use serde::Deserialize;

use crate::{LightcraftApp, theme::Tokens};

const INVENTORY: &str = include_str!("../../../assets/licences/third-party.json");

/// The list's height: the About dialog is a fixed-size, centred window.
const LIST_HEIGHT: f32 = 360.0;
const LIST_WIDTH: f32 = 230.0;
/// The terms column: together with the list it fits the About dialog's width, so opening this tab
/// doesn't widen the window.
const TEXT_WIDTH: f32 = 420.0;

/// One thing the list offers to read: LightCraft itself, the UI font, or a third-party crate.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub name: String,
    pub version: String,
    /// As declared (an SPDX expression).
    pub licence: String,
    /// The licence(s) LightCraft uses it under, when it offers a choice.
    pub used_under: Vec<String>,
    pub authors: Vec<String>,
    pub repository: Option<String>,
    /// The crate publishes no licence file: `texts` are the standard texts of its licences.
    pub standard_texts: bool,
    /// Indices into [`Licences::texts`].
    pub texts: Vec<usize>,
}

/// A licence or notice text, shared by every entry that ships the same words.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct Text {
    pub title: String,
    pub text: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Licences {
    pub entries: Vec<Entry>,
    pub texts: Vec<Text>,
}

/// The generator's record of one crate (`xtask/src/licences.rs`).
#[derive(Deserialize)]
struct Package {
    name: String,
    version: String,
    licence: String,
    complies_with: Vec<String>,
    #[serde(default)]
    authors: Vec<String>,
    repository: Option<String>,
    texts: Vec<usize>,
    standard_texts: bool,
}

#[derive(Deserialize)]
struct Inventory {
    packages: Vec<Package>,
    texts: Vec<Text>,
}

/// LightCraft's own entries, listed before the crates: (name, licence, [(title, text)]).
fn own_entries() -> [(&'static str, &'static str, Vec<(&'static str, &'static str)>); 2] {
    [
        (
            "LightCraft",
            "MIT OR Apache-2.0",
            vec![
                ("NOTICE", include_str!("../../../NOTICE")),
                ("LICENSE-MIT", include_str!("../../../LICENSE-MIT")),
                ("LICENSE-APACHE", include_str!("../../../LICENSE-APACHE")),
            ],
        ),
        ("Inter (UI font)", "OFL-1.1", vec![("OFL-Inter.txt", include_str!("../../../assets/fonts/OFL-Inter.txt"))]),
    ]
}

impl Licences {
    /// LightCraft's own entries followed by the crates of `inventory` (the generator's JSON).
    pub fn parse(inventory: &str) -> Result<Licences, String> {
        let inv: Inventory = serde_json::from_str(inventory).map_err(|e| format!("the licence list is damaged: {e}"))?;
        let mut texts = inv.texts;
        let shared = texts.len();
        let mut entries = Vec::new();
        for (name, licence, own) in own_entries() {
            let first = texts.len();
            texts.extend(own.iter().map(|(title, text)| Text { title: (*title).to_string(), text: text.trim().to_string() }));
            entries.push(Entry {
                name: name.to_string(),
                version: String::new(),
                licence: licence.to_string(),
                used_under: Vec::new(),
                authors: Vec::new(),
                repository: None,
                standard_texts: false,
                texts: (first..texts.len()).collect(),
            });
        }
        for p in inv.packages {
            if let Some(bad) = p.texts.iter().find(|i| **i >= shared) {
                return Err(format!("the licence list is damaged: {} refers to text {bad} of {shared}", p.name));
            }
            let used_under = if p.complies_with.len() == 1 && p.complies_with.first() == Some(&p.licence) { Vec::new() } else { p.complies_with };
            entries.push(Entry {
                name: p.name,
                version: p.version,
                licence: p.licence,
                used_under,
                authors: p.authors,
                repository: p.repository,
                standard_texts: p.standard_texts,
                texts: p.texts,
            });
        }
        Ok(Licences { entries, texts })
    }

    /// The compiled-in list, parsed once.
    pub fn get() -> Result<&'static Licences, &'static str> {
        static LICENCES: std::sync::OnceLock<Result<Licences, String>> = std::sync::OnceLock::new();
        LICENCES.get_or_init(|| Licences::parse(INVENTORY)).as_ref().map_err(String::as_str)
    }

    /// Indices of the entries whose name or licence contains `filter` (any case); all for "".
    pub fn matching(&self, filter: &str) -> Vec<usize> {
        let needle = filter.trim().to_lowercase();
        let hit = |e: &Entry| needle.is_empty() || e.name.to_lowercase().contains(&needle) || e.licence.to_lowercase().contains(&needle);
        self.entries.iter().enumerate().filter(|(_, e)| hit(e)).map(|(i, _)| i).collect()
    }
}

/// What the tab remembers between frames.
#[derive(Clone, Default)]
struct View {
    filter: String,
    /// Index into [`Licences::entries`].
    selected: usize,
}

/// About ▸ Licences: a filterable list on the left, the chosen entry's terms on the right.
pub fn licences_ui(app: &mut LightcraftApp, ui: &mut egui::Ui) {
    let licences = match Licences::get() {
        Ok(l) => l,
        Err(e) => {
            ui.label(crate::i18n::tr(e));
            return;
        }
    };
    let t = Tokens::get(ui.ctx());
    let id = egui::Id::new("licences_view");
    let mut v = ui.data_mut(|d| d.get_temp::<View>(id)).unwrap_or_default();
    ui.horizontal(|ui| {
        crate::text_field::TextField::singleline("field:licenceFilter", &mut v.filter)
            .hint(crate::i18n::tr("Filter by name or licence"))
            .width(LIST_WIDTH)
            .show(ui);
        ui.label(egui::RichText::new(crate::i18n::tr("LightCraft and the components it is built from")).color(t.text_dim));
    });
    let shown = licences.matching(&v.filter);
    let list_h = crate::panels::dialogs::list_height(ui, LIST_HEIGHT);
    ui.horizontal_top(|ui| {
        // bounds the separator, which would otherwise grow the window to the screen's height
        ui.set_height(list_h);
        ui.vertical(|ui| {
            ui.set_width(LIST_WIDTH);
            egui::ScrollArea::vertical().id_salt("licences_list").max_height(list_h).auto_shrink([false, false]).show_rows(
                ui,
                ui.spacing().interact_size.y,
                shown.len(),
                |ui, rows| {
                    for i in shown.get(rows).unwrap_or_default() {
                        let Some(e) = licences.entries.get(*i) else { continue };
                        let label = if e.version.is_empty() { e.name.clone() } else { format!("{} {}", e.name, e.version) };
                        let r = ui.selectable_label(v.selected == *i, label).on_hover_text(&e.licence);
                        crate::widgets::register(ui.ctx(), format!("licence:{}", e.name), r.rect);
                        if r.clicked() {
                            v.selected = *i;
                        }
                    }
                },
            );
        });
        ui.separator();
        ui.vertical(|ui| {
            ui.set_width(TEXT_WIDTH);
            egui::ScrollArea::vertical().id_salt("licences_text").max_height(list_h).auto_shrink([false, false]).show(ui, |ui| {
                if let Some(e) = licences.entries.get(v.selected) {
                    entry_ui(app, ui, &t, licences, e);
                }
            });
        });
    });
    ui.data_mut(|d| d.insert_temp(id, v));
}

fn entry_ui(app: &mut LightcraftApp, ui: &mut egui::Ui, t: &Tokens, licences: &Licences, e: &Entry) {
    let dim = |s: String| egui::RichText::new(s).color(t.text_dim);
    ui.label(egui::RichText::new(format!("{} {}", e.name, e.version).trim().to_string()).font(t.semibold(15.0)).color(t.text));
    ui.label(dim(format!("{}: {}", crate::i18n::tr("Licence"), e.licence)));
    if !e.used_under.is_empty() {
        ui.label(dim(format!("{}: {}", crate::i18n::tr("Used under"), e.used_under.join(" AND "))));
    }
    if !e.authors.is_empty() {
        ui.label(dim(format!("{}: {}", crate::i18n::tr("Authors"), e.authors.join(", "))));
    }
    if let Some(url) = &e.repository
        && ui.link(url).clicked()
    {
        let _ = crate::links::open(app, url);
    }
    if e.standard_texts {
        ui.label(dim(crate::i18n::tr("This component publishes no licence file; the standard text of its licence follows.").to_string()));
    }
    for text in e.texts.iter().filter_map(|i| licences.texts.get(*i)) {
        ui.add_space(8.0);
        ui.label(egui::RichText::new(&text.title).strong());
        ui.label(egui::RichText::new(&text.text).monospace().size(11.0));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_committed_inventory_is_compiled_in() {
        let l = Licences::get().unwrap();
        assert_eq!(l.entries[0].name, "LightCraft");
        assert!(l.texts[l.entries[0].texts[0]].text.contains("ArtCraft Team and the LightCraft contributors"), "NOTICE comes first");
        for name in ["egui", "serde", "wgpu"] {
            assert!(l.entries.iter().any(|e| e.name == name), "{name} is listed");
        }
        assert!(l.entries.iter().all(|e| !e.texts.is_empty()), "every entry has its terms");
        assert!(l.entries.iter().all(|e| !e.licence.contains("GPL") || !e.used_under.is_empty()), "GPL is only ever an alternative not taken");
    }

    #[test]
    fn crates_offering_a_choice_say_which_applies() {
        let json = r#"{"packages": [
            {"name": "a", "version": "1.0.0", "licence": "MIT", "complies_with": ["MIT"], "repository": null, "texts": [0], "standard_texts": false},
            {"name": "b", "version": "2.0.0", "licence": "Apache-2.0 OR GPL-2.0-only", "complies_with": ["Apache-2.0"], "authors": ["B"], "repository": "https://example.org/b", "texts": [0], "standard_texts": true}
        ], "texts": [{"title": "LICENSE", "text": "terms"}]}"#;
        let l = Licences::parse(json).unwrap();
        let (own, a, b) = (&l.entries[0], &l.entries[2], &l.entries[3]);
        assert_eq!((own.name.as_str(), own.texts.len()), ("LightCraft", 3));
        assert!(a.used_under.is_empty(), "nothing to choose");
        assert_eq!(b.used_under, ["Apache-2.0"]);
        assert_eq!(l.texts[b.texts[0]].text, "terms");
    }

    /// A damaged list is an error to show, not a panic.
    #[test]
    fn a_damaged_list_is_an_error() {
        assert!(Licences::parse("{").is_err());
        let out_of_range = r#"{"packages": [{"name": "a", "version": "1", "licence": "MIT", "complies_with": ["MIT"],
            "repository": null, "texts": [1], "standard_texts": false}], "texts": [{"title": "t", "text": "x"}]}"#;
        assert!(Licences::parse(out_of_range).unwrap_err().contains("refers to text 1"));
    }

    #[test]
    fn the_filter_matches_names_and_licences() {
        let l = Licences::get().unwrap();
        assert_eq!(l.matching("").len(), l.entries.len());
        assert_eq!(l.matching("  LIGHTCRAFT ").first(), Some(&0));
        let ofl = l.matching("ofl");
        assert!(ofl.iter().any(|i| l.entries[*i].name.starts_with("Inter")), "{ofl:?}");
        assert!(l.matching("no-such-crate-or-licence").is_empty());
    }
}
